  function load() {
    try { state.data=JSON.parse(localStorage.getItem(STORAGE_KEY))||seed(); }
    catch (_) { state.data=seed(); }
    if (!state.data.schemaVersion || state.data.schemaVersion < 2) state.data=seed();
    if (!state.data.favorites || typeof state.data.favorites!=='object') state.data.favorites={groupId:'',siteIds:[]};
    if (!Array.isArray(state.data.favorites.siteIds)) state.data.favorites.siteIds=[];
    if (!state.data.groups.some(group=>group.id===state.data.favorites.groupId)) state.data.favorites.groupId='';
    state.data.favorites.siteIds=state.data.favorites.siteIds.filter(id=>state.data.sites.some(site=>site.uid===id));
    state.data.sites.forEach(site=>{site.province=site.province||provinceFromAddress(site.address);site.latitude=normalizeCoordinate(site.latitude,'lat');site.longitude=normalizeCoordinate(site.longitude,'lng');});
    state.data.equipment.forEach(item=>{item.latitude=normalizeCoordinate(item.latitude,'lat');item.longitude=normalizeCoordinate(item.longitude,'lng');});
    save();
  }
  function save() { localStorage.setItem(STORAGE_KEY,JSON.stringify(state.data)); }
  function persist(message) { save(); render(); notify(message||'บันทึกในเครื่องแล้ว'); }
