  function directionsUrl(item) {if(!hasCoordinates(item))return '';const destination=`${Number(item.latitude)},${Number(item.longitude)}`;return `https://www.google.com/maps/dir/?api=1&destination=${encodeURIComponent(destination)}&travelmode=driving`;}
