  function loadGoogleMaps() {if(window.google?.maps?.Map)return Promise.resolve(window.google.maps);if(googleMapsPromise)return googleMapsPromise;const config=window.LINE_EXPENSE_CONFIG||{},apiKey=String(config.googleMapsApiKey||'').trim();if(!apiKey)return Promise.reject(new Error('ยังไม่ได้ตั้งค่า GOOGLE_MAPS_API_KEY'));googleMapsPromise=new Promise((resolve,reject)=>{const callback=`workhubGoogleMapsReady_${Date.now()}`;window[callback]=()=>{delete window[callback];resolve(window.google.maps);};const script=document.createElement('script');script.async=true;script.src=`https://maps.googleapis.com/maps/api/js?key=${encodeURIComponent(apiKey)}&libraries=marker&loading=async&callback=${callback}`;script.onerror=()=>{delete window[callback];googleMapsPromise=null;reject(new Error('โหลด Google Maps ไม่สำเร็จ'));};document.head.appendChild(script);});return googleMapsPromise;}
