  function addMyLocationControl(maps,map,{AdvancedMarkerElement,PinElement}) {const button=document.createElement('button');button.type='button';button.className='workhub-map-location';button.title='ซูมไปยังตำแหน่งของฉัน';button.setAttribute('aria-label','ซูมไปยังตำแหน่งของฉัน');button.innerHTML='<span>⌾</span><strong>ตำแหน่งฉัน</strong>';let currentMarker=null;button.addEventListener('click',async()=>{if(button.disabled)return;button.disabled=true;button.classList.remove('is-error');button.querySelector('strong').textContent='กำลังค้นหา…';const location=await browserLocation();if(!location){button.classList.add('is-error');button.querySelector('strong').textContent='ไม่พบตำแหน่ง';setTimeout(()=>{button.disabled=false;button.classList.remove('is-error');button.querySelector('strong').textContent='ตำแหน่งฉัน';},2200);return;}map.panTo(location);map.setZoom(18);if(currentMarker)currentMarker.position=location;else{const pin=new PinElement({background:'#2463a9',borderColor:'#fff',glyphColor:'#fff',glyph:'ฉ',scale:1.05});currentMarker=new AdvancedMarkerElement({map,position:location,title:'ตำแหน่งของฉัน',content:pin.element});}button.querySelector('strong').textContent='ตำแหน่งฉัน';button.disabled=false;});map.controls[maps.ControlPosition.RIGHT_BOTTOM].push(button);}
